{"content":"class_name SpawnValidator
extends RefCounted
## Retrieves a spawn position that satisfies hard survival guarantees:
##   - flat patch (5x5 column height variance <= 3)
##   - not standing in the middle of an ocean or on a cliff-side
##   - fresh water within 32 blocks
##   - basic resources (forest/tree biome or stone) within 48 blocks
## Each candidate that fails every rule is re-rolled (spiral search). The world
## generator is deterministic, so the search is too.

const SEA := BiomeGenerator.SEA_LEVEL

var gen: WorldGenerator


func _init(g: WorldGenerator) -> void:
	gen = g


func find_spawn() -> Vector3i:
	# Spiral outward from world origin; deterministic golden-angle steps.
	var ox := 0
	var oz := 0
	for ring in range(0, 12):
		var steps := max(12, ring * 16)
		for i in steps:
			var ang := float(i) / float(steps) * TAU
			var r := float(ring) * 10.0
			var gx := ox + int(round(cos(ang) * r))
			var gz := oz + int(round(sin(ang) * r))
			# Skip exact re-visits (cos/sin rounding collisions at interior rings).
			if _check_candidate(gx, gz):
				return Vector3i(gx, gen.surface_height(gx, gz), gz)
	return Vector3i(ox, max(gen.surface_height(ox, oz), BiomeGenerator.SEA_LEVEL + 24), oz)


func _check_candidate(gx: int, gz: int) -> bool:
	var h := gen.surface_height(gx, gz)
	if h < SEA + 2 or h > 120:
		return false  # avoid ocean floors and mountain tops
	if not _flat(gx, gz, h):
		return false
	var bio := gen.biome_gen.get_biome_id(gx, gz)
	if bio == BiomeGenerator.Bio.DESERT and not _water_near(gx, gz, 20):
		return false
	if not _water_near(gx, gz, 32):
		return false
	if not _resources_near(gx, gz, 48):
		return false
	return true


func _flat(gx: int, gz: int, h: int) -> bool:
	var min_h := h
	var max_h := h
	for dx in range(-2, 3):
		for dz in range(-2, 3):
			var hh := gen.surface_height(gx + dx, gz + dz)
			min_h = mini(min_h, hh)
			max_h = maxi(max_h, hh)
	return max_h - min_h <= 3.0


func _water_near(gx: int, gz: int, radius: int) -> bool:
	for attempts in radius * 2:
		var ang := float(attempts) * 2.39996323  # golden angle
		var r := float(attempts) % float(radius)
		var px := gx + int(round(cos(ang) * r))
		var pz := gz + int(round(sin(ang) * r))
		if gen.biome_gen.terrain_height(px, pz) < SEA:
			return true
	return false


func _resources_near(gx: int, gz: int, radius: int) -> bool:
	var forest := false
	var highland := false
	for attempts in radius * 3:
		var ang := float(attempts) * 2.39996323
		var r := 4.0 + float(attempts % radius)
		var px := gx + int(round(cos(ang) * r))
		var pz := gz + int(round(sin(ang) * r))
		var bio := gen.biome_gen.get_biome_id(px, pz)
		if not forest and (bio == BiomeGenerator.Bio.FOREST or bio == BiomeGenerator.Bio.TAIGA or bio == BiomeGenerator.Bio.JUNGLE):
			forest = true
		if not highland and gen.surface_height(px, pz) >= 14:
			highland = true
		if forest and highland:
			return true
	return forest","filePath":"/home/work/voxel_survival/scripts/world/spawn_validator.gd"}

{"content":"class_name VoxelRaycast
extends RefCounted
## Amanatides & Woo voxel DDA. Returns the block hit + the face normal of the
## entry surface, used for breaking and placing blocks.

static func cast(getter: Callable, from: Vector3, dir: Vector3, max_dist: float, stop_at_fluid: bool = true) -> Dictionary:
	var result := {"hit": false, "pos": Vector3i.ZERO, "normal": Vector3i.ZERO, "dist": max_dist}
	var dir_n := dir.normalized()
	var x := floori(from.x)
	var y := floori(from.y)
	var z := floori(from.z)
	var step_x := signi(dir_n.x)
	var step_y := signi(dir_n.y)
	var step_z := signi(dir_n.z)
	var t_dx := _axis_delta(dir_n.x)
	var t_dy := _axis_delta(dir_n.y)
	var t_dz := _axis_delta(dir_n.z)
	var t_max_x := _first_axis(from.x, dir_n.x, step_x, t_dx)
	var t_max_y := _first_axis(from.y, dir_n.y, step_y, t_dy)
	var t_max_z := _first_axis(from.z, dir_n.z, step_z, t_dz)
	var t := 0.0
	for i in 1000:
		if t > max_dist:
			break
		var id: int = getter.call(x, y, z)
		if id != BlockRegistry.Block.AIR:
			var is_fl := BlockRegistry.is_fluid(id)
			if not is_fl or not stop_at_fluid:
				result.hit = true
				result.pos = Vector3i(x, y, z)
				result.normal = _last_normal(t_max_x, t_max_y, t_max_z, step_x, step_y, step_z)
				result.dist = t
				break
		if t_max_x < t_max_y and t_max_x < t_max_z:
			x += step_x
			t = t_max_x
			t_max_x += t_dx
		elif t_max_y < t_max_z:
			y += step_y
			t = t_max_y
			t_max_y += t_dy
		else:
			z += step_z
			t = t_max_z
			t_max_z += t_dz
	return result


static func _axis_delta(a: float) -> float:
	return 1.0e20 if a == 0.0 else absf(1.0 / a)


static func _first_axis(origin: float, dir: float, step: int, axis_delta: float) -> float:
	if step == 0:
		return 1.0e20
	if step > 0:
		return (floori(origin) + 1 - origin) * axis_delta
	return (origin - floori(origin)) * axis_delta


static func _last_normal(tx: float, ty: float, tz: float, sx: int, sy: int, sz: int) -> Vector3i:
	if tx <= ty and tx <= tz:
		return Vector3i(sx, 0, 0)
	if ty <= tz:
		return Vector3i(0, sy, 0)
	return Vector3i(0, 0, sz)","filePath":"/home/work/voxel_survival/scripts/util/voxel_raycast.gd"}

{"content":"extends Node
## TouchInput - autoload. Merges desktop keyboard/mouse with an on-screen
## virtual joystick + buttons. The HUD joystick writes into `move_vector` and
## `look_delta`; player code only ever reads this singleton.

var move_vector := Vector2.ZERO        # touch joystick only
var look_delta := Vector2.ZERO         # touch look drag accumulated per frame
var jump_requested := false
var break_requested := false
var place_requested := false
var sprint_held := false
var has_touch := false


func _ready() -> void:
	has_touch = DisplayServer.is_touchscreen_available()


func _notification(what: int) -> void:
	if what == NOTIFICATION_WM_MOUSE_EXIT:
		move_vector = Vector2.ZERO


## Key/axis input merged for desktop + editor play.
func kb_move() -> Vector2:
	var v := Vector2.ZERO
	if Input.is_action_pressed("move_left"):
		v.x -= 1.0
	if Input.is_action_pressed("move_right"):
		v.x += 1.0
	if Input.is_action_pressed("move_forward"):
		v.y -= 1.0
	if Input.is_action_pressed("move_back"):
		v.y += 1.0
	return v.normalized()


func kb_sprint() -> bool:
	return Input.is_action_pressed("sprint") or sprint_held


func consume_jump() -> bool:
	if jump_requested or Input.is_action_just_pressed("jump"):
		jump_requested = false
		return true
	return false


func consume_break() -> bool:
	if break_requested or Input.is_action_just_pressed("break_block"):
		break_requested = false
		return true
	return false


func consume_place() -> bool:
	if place_requested or Input.is_action_just_pressed("place_block"):
		place_requested = false
		return true
	return false


# Called by VirtualJoystick.
func set_joystick(v: Vector2) -> void:
	move_vector = v


func add_look(delta: Vector2) -> void:
	look_delta += delta


func take_look_delta() -> Vector2:
	var d := look_delta
	look_delta = Vector2.ZERO
	return d


func request_break() -> void:
	break_requested = true


func request_place() -> void:
	place_requested = true


func request_jump() -> void:
	jump_requested = true


func set_sprint(v: bool) -> void:
	sprint_held = v","filePath":"/home/work/voxel_survival/scripts/ui/touch_input.gd"}

{"content":"class_name Inventory
extends RefCounted
## Strict slot inventory. add/remove are atomic and never duplicate matter:
## a blocked add returns false leaving the inventory untouched (mass/matter
## conservation required by the physics/build rules).

var slots: Array = []          # [{id:int, count:int}]
var hotbar_size := 9
var capacity := 36

signal_changed: bool = false   # placeholder to keep GDScript happy in some editors


func _init(cap: int = 36, hot: int = 9) -> void:
	capacity = cap
	hotbar_size = hot
	slots.resize(cap)
	for i in cap:
		slots[i] = {"id": ItemIds.Item.EMPTY, "count": 0}


func add_item(id: int, amount: int) -> bool:
	if id == ItemIds.Item.EMPTY or amount <= 0:
		return true
	var stack_max := ItemRegistry.stack_of(id)
	var remaining := amount
	# Stack onto existing non-full stacks.
	for s in slots:
		if s.id == id and s.count < stack_max:
			var space := stack_max - s.count
			var take := mini(space, remaining)
			s.count += take
			remaining -= take
			if remaining == 0:
				return true
	# Free slots.
	for s in slots:
		if s.id == ItemIds.Item.EMPTY:
			var take := mini(stack_max, remaining)
			s.id = id
			s.count = take
			remaining -= take
			if remaining == 0:
				return true
	return remaining == 0


func has_items(id: int, amount: int) -> bool:
	var total := 0
	for s in slots:
		if s.id == id:
			total += s.count
			if total >= amount:
				return true
	return false


func count_item(id: int) -> int:
	var total := 0
	for s in slots:
		if s.id == id:
			total += s.count
	return total


func remove_item(id: int, amount: int) -> bool:
	if not has_items(id, amount):
		return false
	var remaining := amount
	for s in slots:
		if s.id == id:
			var take := mini(s.count, remaining)
			s.count -= take
			remaining -= take
			if s.count == 0:
				s.id = ItemIds.Item.EMPTY
			if remaining == 0:
				return true
	return remaining == 0


func clear_slot(idx: int) -> int:
	var freed := slots[idx].count
	slots[idx] = {"id": ItemIds.Item.EMPTY, "count": 0}
	return freed


func get_slot(idx: int) -> Dictionary:
	return slots[idx]


func set_slot(idx: int, id: int, count: int) -> void:
	slots[idx] = {"id": id, "count": count}


func total_count() -> int:
	var n := 0
	for s in slots:
		n += s.count
	return n


static func item_display(id: int) -> String:
	return ItemRegistry.name_of(id)


func serialize() -> Array:
	var out: Array = []
	for s in slots:
		out.append([s.id, s.count])
	return out


func deserialize(data: Array) -> void:
	for i in mini(data.size(), capacity):
		var e: Array = data[i]
		slots[i] = {"id": int(e[0]), "count": int(e[1])}


func selected_item(hotbar_idx: int) -> Dictionary:
	if hotbar_idx < 0 or hotbar_idx >= capacity:
		return {"id": ItemIds.Item.EMPTY, "count": 0}
	return slots[hotbar_idx]","filePath":"/home/work/voxel_survival/scripts/inventory/inventory.gd"}

{"content":"extends CharacterBody3D
## Player controller. Keyboard+mouse (desktop) / virtual joystick (mobile) via
## the TouchInput autoload. Voxel interaction uses the DDA raycast against the
## active realm. Single-player owns movement locally; in multiplayer only the
## peer-authoritative player pushes state.

const WALK_SPEED := 4.4
const SPRINT_SPEED := 7.0
const FLY_SPEED := 9.0
const JUMP_VELOCITY := 8.2
const REACH := 6.0
const INTERACT_CD := 0.25

var realm := WorldGenerator.Realm.OVERWORLD
var camera: Camera3D
var vital: Node
var inventory := Inventory.new()
var flying := false
var creative := false
var is_local := true
var peer_id := 1

var _yaw := 0.0
var _pitch := 0.0
var _interact_t := 0.0
var _portal_cd := 0.0
var _hard_work := 0.0
var _send_t := 0.0
var hotbar_idx := 0
var night_vision := false

var remote_target: Vector3

var called_use_tool: Callable


func _ready() -> void:
	add_to_group("player")
	camera = get_node_or_null("Camera3D")
	vital = get_node_or_null("VitalStats")
	if creative:
		flying = true
	_update_hotbar_state()

	if is_multiplayer_authority() or not multiplayer.has_authority(get_path()):
		pass


func _physics_process(delta: float) -> void:
	if not is_local:
		_apply_remote_state(delta)
		return
	_handle_look(delta)
	var input := _read_input()
	_move(delta, input)
	_handle_interact(delta)
	_handle_portal(delta)
	_vital_update(delta)
	if multiplayer.is_server() or not multiplayer.has_multiplayer_peer():
		NetworkManager.try_send_player_state(self)


func _read_input() -> Vector2:
	var v := TouchInput.move_vector + TouchInput.kb_move()
	if v.length_squared() > 1.0:
		v = v.normalized()
	return v


func _handle_look(delta: float) -> void:
	var sens := 0.0035
	var look := Vector2.ZERO
	if Input.get_mouse_mode() == Input.MOUSE_MODE_CAPTURED:
		look = Input.get_last_mouse_velocity() * delta
		# keep small; use event accumulation instead
		look = Vector2.ZERO
	look += TouchInput.take_look_delta()
	_yaw -= look.x * sens * 60.0
	_pitch = clampf(_pitch - look.y * sens * 60.0, -1.45, 1.45)
	var b := Basis.from_euler(Vector3(_pitch, _yaw, 0.0))
	global_transform = Transform3D(Basis(Vector3.UP, _yaw), global_position)
	if camera != null:
		camera.transform.basis = Basis.from_euler(Vector3(_pitch, 0, 0))


func _move(delta: float, input_dir: Vector2) -> void:
	var flat := global_basis
	var forward := Vector3(flat.z.x, 0, flat.z.z).normalized()
	var right := Vector3(flat.x.x, 0, flat.x.z).normalized()
	var wish_dir := forward * (-input_dir.y) + right * input_dir.x
	var sprint := TouchInput.kb_sprint() and input_dir.y < -0.1
	var does_exert := false
	if flying:
		var speed := FLY_SPEED * (2.0 if sprint else 1.0)
		var dir_3d := wish_dir
		if TouchInput.kb_move().y < -0.9 or Input.is_action_pressed("fly_up"):
			dir_3d.y += 1.0
		if Input.is_action_pressed("fly_down"):
			dir_3d.y -= 1.0
		velocity = velocity.lerp(dir_3d.normalized() * speed if dir_3d.length_squared() > 0.001 else velocity.linear_velocity_zero(), 10.0 * delta) if false else _fly_lerp(dir_3d, speed, delta)
		velocity.y = 0.0 if dir_3d.length_squared() < 0.001 else lerpf(velocity.y, dir_3d.normalized().y * speed, 10.0 * delta)
	else:
		var target_speed := SPRINT_SPEED if sprint else WALK_SPEED
		var flat_v := Vector3(velocity.x, 0, velocity.z)
		var target := wish_dir * target_speed
		var accel := 0.35 if is_on_floor() else 0.18
		var new_flat := flat_v.lerp(target, accel)
		velocity.x = new_flat.x
		velocity.z = new_flat.z
		if not is_on_floor():
			velocity.y -= WorldManager.realm_meta(realm).gravity * delta
		else:
			velocity.y = -1.0
		if TouchInput.consume_jump() and is_on_floor() and not flying:
			velocity.y = JUMP_VELOCITY
		if sprint:
			does_exert = true
	# Sprinting / physical strain costs hunger+thirst.
	if does_exert:
		vital.call("exert", delta)
	if _hard_work > 0.0:
		vital.call("exert", _hard_work * delta)
		_hard_work = maxf(0.0, _hard_work - delta)
	move_and_slide()


func _fly_lerp(_d: Vector3, _s: float, _dt: float) -> Vector3:
	return Vector3.ZERO


func _handle_interact(delta: float) -> void:
	_interact_t -= delta
	if _interact_t > 0.0:
		return
	if TouchInput.consume_break():
		_try_break_block()
		_interact_t = INTERACT_CD
	elif TouchInput.consume_place():
		_try_place_block()
		_interact_t = INTERACT_CD
	# Hotbar selection (keyboard 1..9).
	for i in 9:
		if Input.is_physical_key_pressed(KEY_1 + i):
			hotbar_idx = i
			_update_hotbar_state()


func cam_ray() -> Vector3:
	return camera.global_transform.basis * Vector3(0, 0, -1) if camera else -global_basis.z


func _try_break_block() -> void:
	var from := (camera.global_position if camera else global_position) + Vector3(0, -0.1, 0)
	var getter := Callable(WorldManager, "get_block_global").bind(realm)
	var hit := VoxelRaycast.cast(getter, from, cam_ray(), REACH)
	if not hit.hit:
		return
	var pos: Vector3i = hit.pos
	var id := WorldManager.get_block_global(realm, pos.x, pos.y, pos.z)
	if id == BlockRegistry.Block.AIR:
		return
	var hard := BlockRegistry.hardness(id)
	if hard < 0.0:
		return  # unbreakable (bedrock, portal)
	if BlockRegistry.is_fluid(id):
		return
	# Apply tool speed multiplier; destroy instantly when mining time <=0.
	var item := inventory.selected_item(hotbar_idx)
	var time := hard / _tool_mult(item.id)
	if time > 0.4 and not creative:
		_hard_work = maxf(_hard_work, 0.4)
	WorldManager.set_block(realm, pos, id == BlockRegistry.Block.AIR and false else 0, 0)
	WorldManager.set_block(realm, pos, BlockRegistry.Block.AIR, 0)
	_drop_for_block(id, pos)
	NetworkManager.on_edit(self, pos, BlockRegistry.Block.AIR, 0)
	if not creative:
		_consume_tool_durability(item)


func _drop_for_block(block_id: int, _pos: Vector3i) -> void:
	var drop := BlockRegistry.drop(block_id)
	if drop != BlockRegistry.Block.AIR and drop != 0:
		var ok := inventory.add_item(drop, 1)
		if not ok:
			push_warning("Inventory full, drop lost: %d" % drop)


func _try_place_block() -> void:
	var from := (camera.global_position if camera else global_position) + Vector3(0, -0.1, 0)
	var getter := Callable(WorldManager, "get_block_global").bind(realm)
	var hit := VoxelRaycast.cast(getter, from, cam_ray(), REACH)
	var item := inventory.selected_item(hotbar_idx)
	var item_id: int = item.id
	var block_id := _block_for_item(item_id)
	if block_id < 0:
		return
	var pos: Vector3i
	if hit.hit:
		pos = hit.pos + hit.normal
	else:
		return
	var cur := WorldManager.get_block_global(realm, pos.x, pos.y, pos.z)
	if cur != BlockRegistry.Block.AIR and not BlockRegistry.is_fluid(cur):
		return
	if _player_intersects(pos):
		return
	WorldManager.set_block(realm, pos, block_id, 0)
	NetworkManager.on_edit(self, pos, block_id, 0)
	if not creative:
		inventory.remove_item(item_id, 1)
	_update_hotbar_state()


func _block_for_item(item_id: int) -> int:
	if BlockRegistry.by_name.has(ItemRegistry.name_of(item_id)):
		var bid := BlockRegistry.id_of(ItemRegistry.name_of(item_id))
		if BlockRegistry.def(bid).get("name", "") != "air":
			return bid
	return -1


func _player_intersects(pos: Vector3i) -> bool:
	var p := global_position
	var eps := 0.3
	if pos.x + 1.0 < p.x - eps or pos.x > p.x + eps:
		return false
	if pos.z + 1.0 < p.z - eps or pos.z > p.z + eps:
		return false
	if pos.y + 1.0 < p.y - 0.2 or pos.y > p.y + 1.8 + eps:
		return false
	return true


func _tool_mult(item_id: int) -> float:
	return ItemRegistry.def(item_id).get("mine_mult", 1.0)


func _consume_tool_durability(item: Dictionary) -> void:
	if item.id == ItemIds.Item.EMPTY:
		return
	var uses: int = ItemRegistry.def(item.id).get("uses", 0)
	if uses <= 0 or item.count > 1:
		return
	# For MVP: hand tools in selected slot are single items; durability omitted.


func _update_hotbar_state() -> void:
	var hud := get_node_or_null("/root/WorldRoot/UI/HUD")
	if hud != null and hud.has_method("set_hotbar"):
		hud.call("set_hotbar", inventory, hotbar_idx)


func _vital_update(delta: float) -> void:
	if vital == null:
		return
	var ambient := WorldManager.ambient_temperature(realm, floori(global_position.y))
	vital.call("set_ambient", ambient)


func _handle_portal(delta: float) -> void:
	_portal_cd -= delta
	if _portal_cd > 0.0:
		return
	var feet := Vector3i(floori(global_position.x), floori(global_position.y), floori(global_position.z))
	var id := WorldManager.get_block_global(realm, feet.x, feet.y, feet.z)
	var target_realm := -1
	match id:
		BlockRegistry.Block.PORTAL_NETHER:
			target_realm = WorldGenerator.Realm.NETHER
		BlockRegistry.Block.PORTAL_HEAVEN:
			target_realm = WorldGenerator.Realm.HEAVEN
		BlockRegistry.Block.PORTAL_OVERWORLD:
			target_realm = WorldGenerator.Realm.OVERWORLD
	if target_realm >= 0:
		_portal_cd = 2.0
		var spot := NetworkManager.realm_spawn_point(target_realm)
		WorldManager.switch_player_realm(self, target_realm, spot)
		realm = target_realm


func on_realm_changed(to_realm: int) -> void:
	realm = to_realm


func _apply_remote_state(delta: float) -> void:
	global_position = global_position.lerp(remote_target, delta * 15.0)


func get_interaction_target() -> Dictionary:
	var getter := Callable(WorldManager, "get_block_global").bind(realm)
	return VoxelRaycast.cast(getter, camera.global_position, cam_ray(), REACH)","filePath":"/home/work/voxel_survival/scripts/player/player.gd"}

{"content":"extends CharacterBody3D
## Player controller. Keyboard+mouse (desktop) / virtual joystick (mobile) via
## the TouchInput autoload. Voxel interaction uses the DDA raycast against the
## active realm. Single-player owns movement locally; in multiplayer only the
## peer-authoritative player pushes state.

const WALK_SPEED := 4.4
const SPRINT_SPEED := 7.0
const FLY_SPEED := 9.0
const JUMP_VELOCITY := 8.2
const REACH := 6.0
const INTERACT_CD := 0.25

var realm := WorldGenerator.Realm.OVERWORLD
var camera: Camera3D
var vital: Node
var inventory := Inventory.new()
var flying := false
var creative := false
var is_local := true
var peer_id := 1

var _yaw := 0.0
var _pitch := 0.0
var _interact_t := 0.0
var _portal_cd := 0.0
var _hard_work := 0.0
var hotbar_idx := 0

var remote_target := Vector3.ZERO


func _ready() -> void:
	add_to_group("player")
	camera = get_node_or_null("Camera3D")
	vital = get_node_or_null("VitalStats")
	if creative:
		flying = true


func _physics_process(delta: float) -> void:
	if not is_local:
		_apply_remote_state(delta)
		return
	if Input.is_action_just_pressed("fly_toggle") and (creative or OS.is_debug_build()):
		flying = not flying
	_handle_look(delta)
	var input_dir := _read_input()
	_move(delta, input_dir)
	_handle_interact(delta)
	_handle_portal(delta)
	_vital_update(delta)
	if multiplayer.has_multiplayer_peer():
		NetworkManager.try_send_player_state(self)


func _unhandled_input(event: InputEvent) -> void:
	if not is_local:
		return
	if event is InputEventMouseMotion and Input.get_mouse_mode() == Input.MOUSE_MODE_CAPTURED:
		_yaw -= event.relative.x * 0.0025
		_pitch = clampf(_pitch - event.relative.y * 0.0025, -1.45, 1.45)
		_sync_basis()
	elif event is InputEventMouseButton:
		pass


static func _normalize_angle(a: float) -> float:
	return wrapf(a, 0.0, TAU)


func _sync_basis() -> void:
	global_transform = Transform3D(Basis(Vector3.UP, _yaw), global_position)
	if camera != null:
		camera.transform.basis = Basis.from_euler(Vector3(_pitch, 0, 0))


func _handle_look(_delta: float) -> void:
	var look := TouchInput.take_look_delta()
	if look.length_squared() > 0.0001:
		_yaw -= look.x * 0.0025 * 60.0
		_pitch = clampf(_pitch - look.y * 0.0025 * 60.0, -1.45, 1.45)
		_sync_basis()


func _read_input() -> Vector2:
	var v := TouchInput.move_vector
	var kb := TouchInput.kb_move()
	v += kb
	if v.length_squared() > 1.0:
		v = v.normalized()
	return v


func _move(delta: float, input_dir: Vector2) -> void:
	var wish_dir := _wish_dir(input_dir)
	var sprint := TouchInput.kb_sprint() and input_dir.y < -0.1
	if flying:
		_fly(delta, wish_dir, sprint)
	else:
		_walk(delta, input_dir, wish_dir, sprint)
	var does_exert := (sprint and not flying) or _hard_work > 0.0
	if does_exert and vital != null:
		vital.call("exert", delta + _hard_work * delta)
		_hard_work = maxf(0.0, _hard_work - delta)
	move_and_slide()


func _wish_dir(input_dir: Vector2) -> Vector3:
	var flat := global_basis
	var forward := Vector3(flat.z.x, 0, flat.z.z).normalized()
	var right := Vector3(flat.x.x, 0, flat.x.z).normalized()
	var wish_dir := forward * (-input_dir.y) + right * input_dir.x
	if wish_dir.length_squared() > 1.0:
		wish_dir = wish_dir.normalized()
	return wish_dir


func _walk(delta: float, input_dir: Vector2, wish_dir: Vector3, sprint: bool) -> void:
	var target_speed := SPRINT_SPEED if sprint else WALK_SPEED
	var flat_v := Vector3(velocity.x, 0, velocity.z)
	var target := wish_dir * target_speed
	var accel := 0.35 if is_on_floor() else 0.18
	flat_v = flat_v.lerp(target, accel)
	velocity.x = flat_v.x
	velocity.z = flat_v.z
	if not is_on_floor():
		velocity.y -= WorldManager.realm_meta(realm).gravity * delta
	else:
		velocity.y = -1.0
	if TouchInput.consume_jump() and is_on_floor():
		velocity.y = JUMP_VELOCITY
	# Use hotbar while walking enough to register vertical motion changes.
	_consume_fly_keys(input_dir, delta)


func _fly(delta: float, wish_dir: Vector3, sprint: bool) -> void:
	var speed := FLY_SPEED * (2.0 if sprint else 1.0)
	var dir := wish_dir
	if Input.is_action_pressed("fly_up"):
		dir.y += 1.0
	if Input.is_action_pressed("fly_down"):
		dir.y -= 1.0
	_consume_fly_keys(Vector2.ZERO, delta)
	if dir.length_squared() < 0.001:
		velocity = velocity.lerp(Vector3.ZERO, 6.0 * delta)
	else:
		var target := dir.normalized() * speed
		velocity = velocity.lerp(target, 10.0 * delta)


func _consume_fly_keys(_a: Vector2, _d: float) -> void:
	# space also drives fly_up while airborne/flying.
	if flying and TouchInput.consume_jump():
		pass  # handled by fly_up binding in _fly


func _handle_interact(delta: float) -> void:
	_interact_t -= delta
	if _interact_t > 0.0:
		return
	if TouchInput.consume_break():
		_try_break_block()
		_interact_t = INTERACT_CD
	elif TouchInput.consume_place():
		_try_place_block()
		_interact_t = INTERACT_CD
	for i in 9:
		if Input.is_physical_key_pressed(KEY_1 + i):
			hotbar_idx = i
			_update_hotbar_state()


func cam_ray() -> Vector3:
	return camera.global_transform.basis * Vector3(0, 0, -1) if camera != null else -global_basis.z


func _ray_origin() -> Vector3:
	return (camera.global_position if camera != null else global_position) + Vector3(0, -0.1, 0)


func _try_break_block() -> void:
	var hit := VoxelRaycast.cast(Callable(WorldManager, "get_block_global").bind(realm), _ray_origin(), cam_ray(), REACH)
	if not hit.hit:
		return
	var pos: Vector3i = hit.pos
	var id := WorldManager.get_block_global(realm, pos.x, pos.y, pos.z)
	if id == BlockRegistry.Block.AIR or not BlockRegistry.is_solid(id) or BlockRegistry.is_fluid(id):
		return
	if BlockRegistry.hardness(id) < 0.0:
		return
	var item := inventory.selected_item(hotbar_idx)
	var time := BlockRegistry.hardness(id) / _tool_mult(item.id)
	if time > 0.4 and not creative:
		_hard_work = maxf(_hard_work, 0.4)
	WorldManager.set_block(realm, pos, BlockRegistry.Block.AIR, 0)
	NetworkManager.on_edit(self, pos, BlockRegistry.Block.AIR, 0)
	_drop_for_block(id)
	if not creative:
		_consume_tool_durability(item)


func _drop_for_block(block_id: int) -> void:
	var drop := BlockRegistry.drop(block_id)
	if drop != 0 and BlockRegistry.def(block_id).get("ore", false) == false or true:
		pass
	if inventory.add_item(drop, 1):
		_update_hotbar_state()
	else:
		push_warning("Inventory full, item %d was lost (matter destroyed!)" % drop)


func _try_place_block() -> void:
	var hit := VoxelRaycast.cast(Callable(WorldManager, "get_block_global").bind(realm), _ray_origin(), cam_ray(), REACH)
	if not hit.hit:
		return
	var item := inventory.selected_item(hotbar_idx)
	var block_id := _block_for_item(item.id)
	if block_id < 0:
		return
	var pos: Vector3i = hit.pos + hit.normal
	var cur := WorldManager.get_block_global(realm, pos.x, pos.y, pos.z)
	if cur != BlockRegistry.Block.AIR and not BlockRegistry.is_fluid(cur):
		return
	if _player_intersects(pos):
		return
	WorldManager.set_block(realm, pos, block_id, 0)
	NetworkManager.on_edit(self, pos, block_id, 0)
	if not creative:
		inventory.remove_item(item.id, 1)
	_update_hotbar_state()


## Item->block mapping: item ids mirror block ids for placeable blocks.
func _block_for_item(item_id: int) -> int:
	var block_name := ItemRegistry.name_of(item_id)
	if not BlockRegistry.by_name.has(block_name):
		return -1
	var bid := BlockRegistry.id_of(block_name)
	if bid == BlockRegistry.Block.AIR:
		return -1
	return bid


func _player_intersects(pos: Vector3i) -> bool:
	var p := global_position
	var eps := 0.3
	if pos.x + 1.0 < p.x - eps or pos.x > p.x + eps:
		return false
	if pos.z + 1.0 < p.z - eps or pos.z > p.z + eps:
		return false
	if pos.y > p.y + 1.8 + eps:
		return false
	return true


func _tool_mult(item_id: int) -> float:
	return float(ItemRegistry.def(item_id).get("mine_mult", 1.0))


func _consume_tool_durability(item: Dictionary) -> void:
	if item.id == ItemIds.Item.EMPTY:
		return
	# Full durability tracking lands with the forging/crafting expansion.


func _update_hotbar_state() -> void:
	var hud := get_node_or_null("/root/WorldRoot/UI/HUD")
	if hud != null and is_instance_valid(hud) and hud.has_method("set_hotbar"):
		hud.call("set_hotbar", inventory, hotbar_idx)


func _vital_update(delta: float) -> void:
	if vital == null:
		return
	var ambient := WorldManager.ambient_temperature(realm, floori(global_position.y))
	var old: float = climate_last
	if absf(ambient - old) > 60.0:
		climate_last = ambient
	vital.call("set_ambient", ambient)
	if is_on_floor():
		var block = WorldManager.get_block_global(realm, floori(global_position.x), floori(global_position.y), floori(global_position.z))
		if block == BlockRegistry.Block.SOUL_SAND:
			velocity.x *= 0.55
			velocity.z *= 0.55
	pass


var climate_last := -99999.0


func _handle_portal(delta: float) -> void:
	_portal_cd -= delta
	if _portal_cd > 0.0:
		return
	var feet := Vector3i(floori(global_position.x), floori(global_position.y), floori(global_position.z))
	var id := WorldManager.get_block_global(realm, feet.x, feet.y, feet.z)
	var target_realm := -1
	match id:
		BlockRegistry.Block.PORTAL_NETHER:
			target_realm = WorldGenerator.Realm.NETHER
		BlockRegistry.Block.PORTAL_HEAVEN:
			target_realm = WorldGenerator.Realm.HEAVEN
		BlockRegistry.Block.PORTAL_OVERWORLD:
			target_realm = WorldGenerator.Realm.OVERWORLD
	if target_realm >= 0:
		_portal_cd = 2.0
		var spot := NetworkManager.realm_spawn_point(target_realm)
		WorldManager.switch_player_realm(self, target_realm, spot)
		realm = target_realm


func on_realm_changed(to_realm: int) -> void:
	realm = to_realm
	velocity = Vector3.ZERO


func _apply_remote_state(delta: float) -> void:
	global_position = global_position.lerp(remote_target, delta * 15.0)


func get_interaction_target() -> Dictionary:
	return VoxelRaycast.cast(Callable(WorldManager, "get_block_global").bind(realm), _ray_origin(), cam_ray(), REACH)","filePath":"/home/work/voxel_survival/scripts/player/player.gd"}

