## RecipeDB - autoload. Central recipe list for crafting / smelting / forging.
## Every recipe is exact on inputs and outputs (mass conservation).
## Forge recipes additionally require a temperature threshold; electric machines
## consume energy, manual work consumes stamina (both enforced at runtime).

## recipe shape:
## { "id", "name", "cat": "craft"|"smelt"|"forge", "station": "none"|"forge"|"forge_electric",
##   "inputs": {ItemIds.Item.X: count}, "outputs": {ItemIds.Item.Y: count},
##   "energy_kj": float, "temp_c": float }

var recipes: Array[Dictionary] = []


func _ready() -> void:
