		"id": "planks", "name": "Planks", "cat": "craft", "station": "none",
		"inputs": {ItemIds.Item.OAK_LOG: 1}, "outputs": {ItemIds.Item.PLANKS: 4}, "energy_kj": 0.0,
	})
	_add({
		"id": "stick", "name": "Sticks", "cat": "craft", "station": "none",
		"inputs": {ItemIds.Item.PLANKS: 1}, "outputs": {ItemIds.Item.STICK: 4}, "energy_kj": 0.0,
	})
	_add({
		"id": "pickaxe_wood", "name": "Wooden Pickaxe", "cat": "craft", "station": "none",
		"inputs": {ItemIds.Item.PLANKS: 3, ItemIds.Item.STICK: 2}, "outputs": {ItemIds.Item.TOOL_PICKAXE_WOOD: 1}, "energy_kj": 0.0,
	})
