	## --- Forging (hot working into blanks) ---
	_add({
		"id": "bronze_ingot", "name": "Bronze Ingot (alloy)", "cat": "forge", "station": "forge",
		"inputs": {ItemIds.Item.INGOT_COPPER: 3, ItemIds.Item.INGOT_TIN: 1}, "outputs": {ItemIds.Item.INGOT_BRONZE: 4}, "energy_kj": 220.0, "temp_c": 950.0,
