func _add(r: Dictionary) -> void:
	r["_id"] = r.id
	recipes.append(r)


func get_recipe(rid: String) -> Dictionary:
	for r in recipes:
		if r.id == rid:
			return r
	return {}


func any_of_cat(cat: String) -> Array[Dictionary]:
