{"content":"class_name Forge
extends RefCounted
## Forge (manual + electric). Encapsulates the metal processing path:
##   ore/smelting already ran in the CraftingManager using fuel heat; the forge
##   handles the *hot working / casting* stage:
##     electric:  E_electric = metal_mass * heat_treatment_coef   (per recipe)
##     manual:    N hammer blows, each drains stamina (hunger), slow + tiring.
##   Conservation: no recipe ever returns energy; electricity/stamina pays the
##   temperature and deformation work, and both are strictly consumed.

enum Type { MANUAL, ELECTRIC }

var type := Type.MANUAL
var pos := Vector3i.ZERO

## Thermal state.
var heat_kj := 0.0
var temperature_c := 20.0
var cooling_per_s := 0.30          # fraction of ΔT lost per second
var heat_added_total := 0.0

## Electric supply (set by EnergySystem when the block is wired).
var network: EnergyNetwork = null
var draw_w := 1000.0               # max electricity the electric forge can pull
var efficiency := 0.75             # electric -> heat (<1)

var input_slots := Inventory.new(12, 4)
var player_inv: Inventory
var armed := true


func _init(kind: int, p: Vector3i) -> void:
	type = kind
	pos = p


## Burn fuel: purely a *load* action - the fuel's full heat content enters the
## hearth. Used by manual forges (and their cooking/smelting side).
func add_fuel(item_id: int, count: int = 1) -> void:
	var kju := ItemRegistry.fuel_kj(item_id)
	if kju <= 0.0:
		return
	heat_kj += kju * count
	heat_added_total += kju * count


## Electric heating: pulls `w * dt` joules from the grid at efficiency, adds to
## heat. Returns the draw so the energy network can deduct it.
func electric_heat_step(dt: float) -> float:
	if network == null or not armed:
		return 0.0
	var want_j := draw_w * dt
	var want_kj := want_j / 1000.0
	var delivered := minf(want_kj, 50.0)   # per-step cap
	heat_kj += delivered * efficiency
	heat_added_total += delivered * efficiency
	_tick_temperature(dt)
	return want_kj


func _tick_temperature(dt: float) -> void:
	# Metal temp rises as heat fills the blank; loses heat to surroundings.
	if heat_kj > 0.0:
		var max_reach := 25.0 + heat_kj * 1.4
		temperature_c += (max_reach - temperature_c) * minf(1.0, dt * 2.0)
	else:
		temperature_c += (20.0 - temperature_c) * minf(1.0, dt * cooling_per_s)


## Cost model: electric forging energy = metal mass * heat-treatment factor.
func electric_energy_for(recipe: Dictionary) -> float:
	var mass := 0.0
	for item_id in recipe.inputs:
		mass += float(ItemRegistry.def(item_id).get("mass", 1.0)) * float(recipe.inputs[item_id])
	var coef := float(recipe.get("energy_kj", 100.0))
	return mass * coef


## A hammer blow: pushes heat in, drains stamina of the blacksmith.
func hammer_hit(stamina_tax: Callable, dt: float = 2.0) -> float:
	var work_kj := 1.6
	heat_kj += work_kj
	_tick_temperature(dt)
	stamina_tax.call(work_kj)   # manual work costs hunger/physical energy
	return work_kj


## Attempt a hot-work recipe with the given player inventory and station type.
## Returns {ok: bool, reason: String}.
func forge_recipe(station: int, player: Inventory, recipe: Dictionary) -> Dictionary:
	var required_temp: float = recipe.get("temp_c", 0.0)
	if temperature_c < required_temp - 5.0:
		return {"ok": false, "reason": "temperature_low"}
	# Forge recipes consume the metal blank (hot) and yield the finished item.
	if type == Type.ELECTRIC:
		var energy := electric_energy_for(recipe)
		var avail := network_energy_available()
		if avail < energy:
			return {"ok": false, "reason": "insufficient_power"}
		if not CraftingManager.craft(player, recipe, station, energy):
			return {"ok": false, "reason": "inputs_missing"}
		_drain_energy(energy)
		heat_kj -= energy * 0.85       # heat leaves with the worked metal
		return {"ok": true, "reason": "ok"}
	# Manual path: each blow advances one unit of work.
	var blows := int(ceil(electric_energy_for(recipe) / 1.6))
	var needs_stamina := blows * 1.6
	if _stamina_left(player) < needs_stamina:
		return {"ok": false, "reason": "tired"}
	if not CraftingManager.craft(player, recipe, station, recipe.get("energy_kj", 0.0)):
		return {"ok": false, "reason": "inputs_missing"}
	_drain_stamina(player, needs_stamina)
	heat_kj -= needs_stamina * 0.85
	return {"ok": true, "reason": "ok"}


func _stamina_left(player: Inventory) -> float:
	# Forge operations use hunger as stamina; later a dedicated stamina bar.
	var hunger: float = player.get("hunger")
	return hunger if hunger != null else 0.0


func _drain_stamina(player: Inventory, amount: float) -> void:
	var hunger: float = player.get("hunger")
	if hunger != null:
		player.set("hunger", maxf(0.0, hunger - amount))


func network_energy_available() -> float:
	if network == null:
		return battery_stored_kj()
	return battery_stored_kj() + network.last_balance.get("consumed_w", 0.0) * 0.0


var _stored_battery_kj := 0.0


func battery_stored_kj() -> float:
	if network == null:
		return 0.0
	var total := 0.0
	for pos in network.nodes:
		var n: EnergyNode = network.node_at(pos)
		if n.kind == EnergyNode.Kind.STORAGE_BATTERY:
			total += n.charge_kj
	return total


func _drain_energy(kj: float) -> void:
	if network == null:
		return
	for pos in network.nodes:
		var n: EnergyNode = network.node_at(pos)
		if n.kind == EnergyNode.Kind.STORAGE_BATTERY and kj > 0.0:
			kj -= n.draw_stored_energy(kj)
			if kj <= 0.0:
				return


func manual_ready(player: Inventory) -> bool:
	return temperature_c >= 800.0 and has_hammer(player)


func has_hammer(player: Inventory) -> bool:
	return player.has_items(ItemIds.Item.HAMMER, 1)","filePath":"/home/work/voxel_survival/scripts/energy/forge.gd"}

