		_drain_energy(energy)
		heat_kj -= energy * 0.85       # heat leaves with the worked metal
		return {"ok": true, "reason": "ok"}
	# Manual path: each blow advances one unit of work.
	var blows := int(ceil(electric_energy_for(recipe) / 1.6))
	var needs_stamina := blows * 1.6
	if _stamina_left(player) < needs_stamina:
		return {"ok": false, "reason": "tired"}
	if not CraftingManager.craft(player, recipe, station, recipe.get("energy_kj", 0.0)):
		return {"ok": false, "reason": "inputs_missing"}
	_drain_stamina(player, needs_stamina)
	heat_kj -= needs_stamina * 0.85
	return {"ok": true, "reason": "ok"}


func _stamina_left(player: Inventory) -> float:
	# Forge operations use hunger as stamina; later a dedicated stamina bar.
	var hunger: float = player.get("hunger")
	return hunger if hunger != null else 0.0


func _drain_stamina(player: Inventory, amount: float) -> void:
	var hunger: float = player.get("hunger")
	if hunger != null:
		player.set("hunger", maxf(0.0, hunger - amount))


func network_energy_available() -> float:
	if network == null:
		return battery_stored_kj()
	return battery_stored_kj() + network.last_balance.get("consumed_w", 0.0) * 0.0"}

{"content":"class_name WorldNavigation
extends Node3D
## NavigationServer3D integration for voxel terrain.
## Maintains one NavigationRegion3D whose NavigationMesh is rebuilt on the fly
## from the chunk collision/ground columns near the tracked position. Any NPC
## with a NavigationAgent3D in the same World3D path-finds across these cells.
## Fallback: `npc_base.gd` uses a voxel A* if the agent has no valid path yet.

const RADIUS_CELLS := 10   # half-extent in voxels around the anchor

var _region: NavigationRegion3D
var _anchor := Vector3(99999, 0, 99999)
var rebuild_wanted := false

var ground_heights := {}   # Vector2i -> ground y (debug/reuse)


func _ready() -> void:
	_region = NavigationRegion3D.new()
	_region.name = "VoxelNavRegion"
	add_child(_region)


func ensure_anchor(anchor: Vector3) -> void:
	if _anchor.distance_to(anchor) > 16.0:
		_anchor = anchor
		rebuild_wanted = true
	if rebuild_wanted and is_inside_tree():
		_rebuild()
		rebuild_wanted = false


func _rebuild() -> void:
	var realm := WorldManager.active_realm
	var c0 := ChunkData.to_chunk(Vector3i(floori(_anchor.x) - RADIUS_CELLS, 0, floori(_anchor.z) - RADIUS_CELLS))
	var c1 := ChunkData.to_chunk(Vector3i(floori(_anchor.x) + RADIUS_CELLS, 0, floori(_anchor.z) + RADIUS_CELLS))
	if c1.x - c0.x > 10 or c1.y - c0.y > 10:
		return
	# Collect ground height per column (topmost solid collidable).
	ground_heights.clear()
	var min_y := 99999
	var max_y := -99999
	var cells := {}
	for x in range(c0.x * ChunkData.CHUNK_X, (c1.x + 1) * ChunkData.CHUNK_X):
		for z in range(c0.y * ChunkData.CHUNK_Z, (c1.y + 1) * ChunkData.CHUNK_Z):
			var gy := find_ground(realm, x, z)
			if gy < 0:
				continue
			ground_heights[Vector2i(x, z)] = gy
			cells[Vector2i(x, z)] = gy
			min_y = mini(min_y, gy)
			max_y = maxi(max_y, gy)
	if cells.is_empty() or max_y - min_y > 40:
		return
	# Build a NavigationMesh: each walkable, *flat* cell becomes two triangles.
	var nm := NavigationMesh.new()
	var idx_of := {}
	var vertices := PackedVector3Array()
	var polygons: Array = []
	for cell in cells:
		var gy: int = cells[cell]
		# Only cells whose 2x2 block is flat within 1 block are linkable.
		var flat := true
		for dx in [0, 1]:
			for dz in [0, 1]:
				var ng := cells.get(Vector2i(cell.x + dx, cell.y + dz), gy + 2)
				if absi(ng - gy) > 1:
					flat = false
		if not flat:
			continue
		var a := Vector3(cell.x, gy, cell.y)
		var b := Vector3(cell.x + 1, gy, cell.y)
		var cc := Vector3(cell.x + 1, gy, cell.y + 1)
		var d := Vector3(cell.x, gy, cell.y + 1)
		var idx: Array[int] = []
		for p in [a, b, cc, d]:
			var key := p
			if not idx_of.has(key):
				idx_of[key] = vertices.size()
				vertices.append(p)
			idx.append(idx_of[key])
		polygons.append([idx[0], idx[1], idx[2]])
		polygons.append([idx[0], idx[2], idx[3]])
	nm.vertices = vertices
	nm.polygons = polygons
	_region.navigation_mesh = nm


## Topmost collidable ground under a column; -1 when none/inside void.
func find_ground(realm: int, x: int, z: int) -> int:
	for y in range(ChunkData.CHUNK_Y - 1, 1, -1):
		var id := WorldManager.get_block_global(realm, x, y, z)
		if id != BlockRegistry.Block.AIR and BlockRegistry.is_collidable(id) \
				and not BlockRegistry.is_fluid(id):
			if WorldManager.get_block_global(realm, x, y + 1, z) == BlockRegistry.Block.AIR:
				return y
	return -1","filePath":"/home/work/voxel_survival/scripts/entities/world_navigation.gd"}

{"content":"class_name VoxelPathfinder
extends RefCounted
## Voxel-grid A* used as the NavigationAgent3D fallback (and as the enforced
## path source in headless tests where no nav mesh exists).
## Movement is 4-connected on a column grid; a move is legal when:
##   - both columns have a walkable ground surface within 1 block delta
##   - the 2-block tall "head" space is clear.

static func ground(realm: int, x: int, z: int) -> int:
	for y in range(ChunkData.CHUNK_Y - 2, 0, -1):
		var id := WorldManager.get_block_global(realm, x, y, z)
		if id != BlockRegistry.Block.AIR and BlockRegistry.is_collidable(id) and not BlockRegistry.is_fluid(id):
			var up := WorldManager.get_block_global(realm, x, y + 1, z)
			if up == BlockRegistry.Block.AIR:
				return y
	return -1


static func step(from: Vector3, to: Vector3, realm: int, max_search: int = 512) -> Vector3:
	var fgx := floori(from.x)
	var fgz := floori(from.z)
	var tgx := floori(to.x)
	var tgz := floori(to.z)
	if fgx == tgx and fgz == tgz:
		return to
	var gy_from := ground(realm, fgx, fgz)
	if gy_from < 0:
		return from
	var open := {}
	var closed := {}
	var g_score := {}
	var f_score := {}
	var came := {}
	var start := Vector2i(fgx, fgz)
	var goal := Vector2i(tgx, tgz)
	open[start] = true
	g_score[start] = 0.0
	f_score[start] = _h(start, goal)
	var iterations := 0
	while not open.is_empty() and iterations < max_search:
		iterations += 1
		# Pop lowest f.
		var cur: Vector2i = _pop_min(open, f_score)
		if cur == goal:
			return _reconstruct(came, start, cur, realm)
		closed[cur] = true
		for nb in _neighbors(cur, goal, realm):
			if closed.has(nb) or open.has(nb):
				# still relax
				pass
			var tentative := g_score[cur] + 1.0
			if tentative < g_score.get(nb, 1e9):
				came[nb] = cur
				g_score[nb] = tentative
				f_score[nb] = tentative + _h(nb, goal)
				open[nb] = true
	return from


static func _reconstruct(came: Dictionary, start: Vector2i, cur: Vector2i, realm: int) -> Vector3:
	var cells: Array[Vector2i] = []
	while cur != start:
		# Heuristic: midi-approx (distances ~1).
		cells.append(cur)
		var prev: Vector2i = came.get(cur, start)
		if prev == cur:
			break
		cur = prev
	cells.reverse()
	var first: Vector2i = cells[0]
	var gy := ground(realm, first.x, first.y)
	if gy < 0:
		gy = 40
	return Vector3(first.x + 0.5, float(gy) + 1.0, first.y + 0.5)


static func _h(a: Vector2i, b: Vector2i) -> float:
	return absi(a.x - b.x) + absi(a.y - b.y)


static func _pop_min(open: Dictionary, f_score: Dictionary) -> Vector2i:
	var best: Vector2i = open.keys()[0]
	var best_f := f_score.get(best, 1e9)
	for k in open:
		var f := f_score.get(k, 1e9)
		if f < best_f:
			best = k
			best_f = f
	open.erase(best)
	return best


static func _neighbors(cell: Vector2i, goal: Vector2i, realm: int) -> Array:
	var out: Array = []
	for d in [Vector2i(1, 0), Vector2i(-1, 0), Vector2i(0, 1), Vector2i(0, -1)]:
		var cand := cell + d
		var gy := ground(realm, cand.x, cand.y)
		if gy < 0:
			continue
		var gcur := ground(realm, cell.x, cell.y)
		if absi(gy - gcur) > 1:
			continue
		# head clearance
		var head := WorldManager.get_block_global(realm, cand.x, gy + 1, cand.y)
		var head2 := WorldManager.get_block_global(realm, cell.x, gcur + 1, cell.y)
		if BlockRegistry.is_solid(head) or BlockRegistry.is_solid(head2):
			continue
		out.append(cand)
	return out","filePath":"/home/work/voxel_survival/scripts/entities/voxel_pathfinder.gd"}

{"content":"extends CharacterBody3D
## Base NPC: physics body + NavigationAgent3D + scripted behaviour state machine.
## Every subclass (Animal, Monster, Angel, God boss) only overrides the
## `on_<state>_*` hooks; the navigation glue lives here.

signal npc_died(npc: Node)
signal aggro_changed(hostile: bool)

const JUMP_VELOCITY := 8.4

var max_health := 20.0
var health := 20.0
var speed := 3.0
var vision_range := 16.0
var attack_damage := 3.0
var attack_cd := 1.2
var hostile := false
var flee_health := 0.2
var realm := WorldGenerator.Realm.OVERWORLD
var use_nav_agent := true

var nav_agent: NavigationAgent3D
var state: AIStateMachine
var target: Node3D = null
var _attack_t := 0.0
var _nav_recompute := 0.0
var _path_target := Vector3.ZERO
var _last_waypoint := Vector3.ZERO
var _anim_speed := 0.0

var anim_tree: AnimationTree = null


func _ready() -> void:
	add_to_group("npc")
	nav_agent = get_node_or_null("NavigationAgent3D")
	anim_tree = get_node_or_null("AnimationTree")
	state = AIStateMachine.new(self)
	health = max_health
	var wp := get_node_or_null("WorldNavAnchor")
	if wp != null:
		var wnav := get_tree().get_first_node_in_group("world_navigation")
		if wnav != null:
			wnav.ensure_anchor(wp.global_position)


func _physics_process(delta: float) -> void:
	_attack_t -= delta
	state.tick(delta)
	_navigate(delta)
	move_and_slide()
	_process_anim(delta)


func target_player() -> Node:
	if target != null and is_instance_valid(target):
		return target
	var players := get_tree().get_nodes_in_group("player")
	if players.is_empty():
		return null
	for p in players:
		if p.get("peer_id", 1):
			target = p
			break
	target = players[0]
	return target


func _navigate(delta: float) -> void:
	_nav_recompute -= delta
	var dest := _desired_point()
	var cur := Vector3(global_position.x, 0, global_position.z)
	var d2x := Vector3(dest.x, 0, dest.z)
	if cur.distance_to(d2x) < 1.2:
		velocity.x = lerpf(velocity.x, 0.0, 6.0 * delta)
		velocity.z = lerpf(velocity.z, 0.0, 6.0 * delta)
		return
	var next := _next_point(dest, delta)
	var dir := next - global_position
	dir.y = 0
	if dir.length_squared() < 0.0001:
		return
	dir = dir.normalized()
	var want := dir * speed
	velocity.x = lerpf(velocity.x, want.x, 8.0 * delta)
	velocity.z = lerpf(velocity.z, want.z, 8.0 * delta)
	velocity.y -= WorldManager.realm_meta(realm).gravity * delta
	# Step/climb one block up when NavAgent suggests height gain.
	if next.y > global_position.y + 0.6 and is_on_floor():
		velocity.y = JUMP_VELOCITY * 0.7
	var rot := Transform3D(Basis(Vector3.UP, atan2(-dir.x, -dir.z)), global_position)
	global_transform = rot
	_anim_speed = want.length()


func _desired_point() -> Vector3:
	match state.current:
		AIStateMachine.State.CHASE, AIStateMachine.State.ATTACK:
			var pl := target_player()
			if pl != null:
				return pl.global_position
		AIStateMachine.State.FLEE:
			var pl := target_player()
			if pl != null:
				return global_position + (global_position - pl.global_position).normalized() * 12.0
	return _path_target


func _next_point(dest: Vector3, _dt: float) -> Vector3:
	if nav_agent != null and nav_agent.is_navigation_finished():
		nav_agent.set_target_position(dest)
	if nav_agent != null and not nav_agent.is_navigation_finished():
		return nav_agent.get_next_path_position()
	# Fallback: voxel A* step.
	if Time.get_ticks_msec() % 500 < 16:
		_last_waypoint = VoxelPathfinder.step(global_position, dest, realm)
		return _last_waypoint
	return _last_waypoint if _last_waypoint != Vector3.ZERO else dest


## ---- Behaviour hooks (state machine -> methods on owner) ----

func on_idle_enter() -> void:
	_passive = true


func on_idle(_dt: float) -> void:
	if target_player() != null:
		var pl := target_player()
		if global_position.distance_to(pl.global_position) < vision_range:
			_transition_from_idle()


func _transition_from_idle() -> void:
	var pl := target_player()
	if pl != null:
		if hostile:
			state.set_state(AIStateMachine.State.CHASE)
		elif global_position.distance_to(pl.global_position) < vision_range * 0.5:
			state.set_state(AIStateMachine.State.FLEE)


func on_chase(_dt: float) -> void:
	if target_player() == null:
		state.set_state(AIStateMachine.State.IDLE)
		return
	if global_position.distance_to(target_player().global_position) < 1.6:
		state.set_state(AIStateMachine.State.ATTACK)
	elif global_position.distance_to(target_player().global_position) > vision_range * 1.6:
		state.set_state(AIStateMachine.State.IDLE)


func on_attack(_dt: float) -> void:
	if target_player() == null or not is_instance_valid(target_player()):
		state.set_state(AIStateMachine.State.IDLE)
		return
	if _attack_t <= 0.0:
		_strike()
		_attack_t = attack_cd
	if global_position.distance_to(target_player().global_position) > 2.4:
		state.set_state(AIStateMachine.State.CHASE)


func on_wander(_dt: float) -> void:
	_passive = false
	if _path_target.distance_to(global_position) < 2.0:
		_pick_wander_target()


func _pick_wander_target() -> void:
	var n := _randpoint(global_position, 8.0)
	_path_target = n


func _randpoint(around: Vector3, radius: float) -> Vector3:
	var a := randf() * TAU
	var r := randf() * radius
	return around + Vector3(cos(a) * r, 0, sin(a) * r)


func on_flee(_dt: float) -> void:
	if health > max_health * flee_health:
		state.set_state(AIStateMachine.State.IDLE)


func on_dead_enter() -> void:
	_collision_layer = 0
	_collision_mask = 0
	velocity = Vector3.ZERO
	npc_died.emit(self)


func take_damage(amount: float, from: Node = null) -> void:
	health -= amount
	if health <= 0.0:
		state.set_state(AIStateMachine.State.DEAD, true)
		queue_free()
		return
	if hostile and from != null:
		target = from
		state.set_state(AIStateMachine.State.CHASE)


func _strike() -> void:
	if target_player() != null:
		target_player().call("take_damage_net", attack_damage, get_path())


func _process_anim(_dt: float) -> void:
	if anim_tree != null:
		anim_tree.set("parameters/BlendSpace/speed", _anim_speed)
	pass


var _passive := true","filePath":"/home/work/voxel_survival/scripts/entities/npc_base.gd"}

