	speed = k_speed
	max_health = hp
	health = hp
	attack_damage = dmg
	hostile = hostile_kind
	attack_cd = 1.1


func on_idle(_dt: float) -> void:
	if night_only and not _is_night():
		state.set_state(AIStateMachine.State.WANDER)
		return
