{"content":"extends CanvasLayer
## HUD: four survival bars, crosshair, hotbar, and the mobile touch overlay.

var root: Control
var _bars := {}
var _bar_labels := {}
var _hotbar_labels: Array = []
var _crosshair: Label


func _ready() -> void:
	root = Control.new()
	root.set_anchors_preset(Control.PRESET_FULL_RECT)
	add_child(root)
	_build_top_panel()
	_build_crosshair()
	_build_hotbar()
	_build_touch_overlay()
	set_process(true)


func _build_top_panel() -> void:
	var panel := PanelContainer.new()
	panel.name = "StatPanel"
	panel.set_anchors_preset(Control.PRESET_TOP_LEFT)
	panel.position = Vector2(10, 10)
	root.add_child(panel)
	var vbox := VBoxContainer.new()
	panel.add_child(vbox)
	for key in ["health", "hunger", "thirst", "temperature"]:
		var hb := HBoxContainer.new()
		var lbl := Label.new()
		lbl.text = key.to_upper()
		lbl.custom_minimum_size = Vector2(92, 0)
		lbl.add_theme_font_size_override("font_size", 13)
		hb.add_child(lbl)
		var bar := ProgressBar.new()
		bar.custom_minimum_size = Vector2(180, 14)
		var color := Color.WHITE
		match key:
			"health":
				color = Color(0.85, 0.2, 0.2)
			"hunger":
				color = Color(0.85, 0.7, 0.2)
			"thirst":
				color = Color(0.25, 0.55, 0.9)
			"temperature":
				color = Color(0.95, 0.45, 0.2)
		bar.add_theme_stylebox_override("fill", _fill_style(color))
		bar.max_value = 100.0
		bar.show_percentage = false
		var val := Label.new()
		val.custom_minimum_size = Vector2(48, 0)
		val.alignment = HORIZONTAL_ALIGNMENT_RIGHT
