func _build_touch_overlay() -> void:
	if not DisplayServer.is_touchscreen_available():
		return
	var joy := preload("res://scripts/ui/virtual_joystick.gd").new()
	joy.name = "Joystick"
	var ctl := Control.new()
	ctl.name = "JoyHost"
	ctl.set_anchors_preset(Control.PRESET_BOTTOM_LEFT)
	ctl.position = Vector2(40, -180)
	ctl.size = Vector2(160, 160)
	ctl.add_child(joy)
	joy.set_anchors_preset(Control.PRESET_FULL_RECT)
	root.add_child(ctl)
	var act := VBoxContainer.new()
	act.set_anchors_preset(Control.PRESET_BOTTOM_RIGHT)
	act.position = Vector2(-170, -200)
	act.add_theme_constant_override("separation", 8)
	root.add_child(act)
	for spec in [
		{"t": "Sprint", "cb": func(_d): _sprint_btn(1), "owner": self},
		{"t": "Place", "cb": func(_d): TouchInput.request_place(), "owner": self},
		{"t": "Break", "cb": func(_d): TouchInput.request_break(), "owner": self},
		{"t": "Jump", "cb": func(_d): TouchInput.request_jump(), "owner": self},
	]:
		var b := Button.new()
		b.text = spec.t
		b.custom_minimum_size = Vector2(110, 42)
		b.add_theme_font_size_override("font_size", 15)
		if spec.t == "Sprint" and spec.has("owner"):
			b.pressed.connect(func(): TouchInput.set_sprint(true))
			b.button_down.connect(func(): TouchInput.set_sprint(true))
			b.button_up.connect(func(): TouchInput.set_sprint(false))
		else:
			b.pressed.connect(spec.cb)
		act.add_child(b)


func _sprint_btn(_n: int) -> void:
	TouchInput.set_sprint(true)


func _process(_delta: float) -> void:
	var player := get_tree().get_first_node_in_group("player")
	if player == null or not is_instance_valid(player):
		return
	var vitals: Node = player.get_node_or_null("VitalStats")
	if vitals != null and vitals.has_method("get_values"):
		var v: Dictionary = vitals.call("get_values")
		_update_bars(v)
	set_hotbar(player.inventory, player.hotbar_idx)


func _update_bars(v: Dictionary) -> void:
	if _bars.has("health"):
		_bars["health"].value = v.health
		_bars["health"].max_value = v.max_health
		_bar_labels["health"].text = "%d" % int(round(v.health))
	if _bars.has("hunger"):
		_bars["hunger"].value = v.hunger
		_bar_labels["hunger"].text = "%d" % int(round(v.hunger))
	if _bars.has("thirst"):
		_bars["thirst"].value = v.thirst
		_bar_labels["thirst"].text = "%d" % int(round(v.thirst))
	if _bars.has("temperature"):
		_bars["temperature"].value = clampf((v.temperature + 20.0) / 70.0 * 100.0, 0.0, 100.0)
		_bar_labels["temperature"].text = "%.0f C" % v.temperature


func set_hotbar(inv, selected: int = 0) -> void:
	for i in _hotbar_labels.size():
		if i >= inv.capacity:
			continue
		var slot: Dictionary = inv.get_slot(i)
		var txt := ""
		if slot.id != ItemIds.Item.EMPTY:
			var name := ItemRegistry.name_of(slot.id)
			txt = "%s\nx%d" % [name.left(8), slot.count]
		var lbl: Label = _hotbar_labels[i]
		lbl.text = txt
		var panel: PanelContainer = lbl.get_parent()
		var style := StyleBoxFlat.new()
		style.bg_color = Color(0.2, 0.5, 0.2, 0.6) if i == selected else Color(0, 0, 0, 0.35)
		style.set_border_width_all(1)
		style.border_color = Color(1, 1, 1, 0.5) if i == selected else Color(1, 1, 1, 0.25)
		panel.add_theme_stylebox_override("panel", style)


func _notification(what: int) -> void:
	if what == NOTIFICATION_WM_GO_BACK_REQUEST and DisplayServer.is_touchscreen_available():
		var tree := get_tree()
		if tree != null and tree.current_scene != null:
			tree.quit()","filePath":"/home/work/voxel_survival/scripts/ui/hud.gd"}

