## Simple virtual joystick for touch. Drag anywhere inside the control; the
## vector is fed to the TouchInput singleton (clamped dead-zone applied).

var _base_center := Vector2.ZERO
var _active := false
var _pointer_id := -1
var _radius := 56.0


func _ready() -> void:
	mouse_filter = Control.MOUSE_FILTER_IGNORE
	_set_size()


func _set_size() -> void:
	custom_minimum_size = Vector2(160, 160)
	size = Vector2(160, 160)


func _gui_input(event: InputEvent) -> void:
	if event is InputEventScreenTouch:
		if event.pressed and not _active:
			_active = true
			_pointer_id = event.index
			_base_center = event.position
		elif not event.pressed and event.index == _pointer_id:
			_release()
	elif event is InputEventScreenDrag and _active and event.index == _pointer_id:
		var delta := event.position - _base_center
		var v := delta / _radius
		if v.length() > 1.0:
			v = v.normalized()
		TouchInput.set_joystick(v)


func _release() -> void:
	_active = false
	_pointer_id = -1
	TouchInput.set_joystick(Vector2.ZERO)


func _unhandled_input(event: InputEvent) -> void:
	if not _active and event is InputEventScreenTouch and event.pressed:
		_gui_input(event)","filePath":"/home/work/voxel_survival/scripts/ui/virtual_joystick.gd"}

{"content":"extends Node
## NetworkManager - autoload. LAN multiplayer (ENetMultiplayerPeer).
##
## Model: host-authoritative world. The world seed is shared so terrain is
## generated deterministically on every client; only *edits on top* travel the
## wire. Host validates edits and relays them to all peers.

const PLAYER_SCENE := "res://scenes/player/player.tscn"
const STATE_INTERVAL := 0.05  # 20 Hz transform sync (LAN-friendly)

var world_seed := 1337
var port := 7777
var is_host := false
var host_ip := "127.0.0.1"
var max_players := 8

var _remote_players := {}   # peer_id -> Node
var _state_timer := 0.0
var _applying_remote := false
var player_scene: PackedScene


func _ready() -> void:
	player_scene = load(PLAYER_SCENE)


func is_online() -> bool:
	return multiplayer.has_multiplayer_peer()


func host_game(seed_value: int = 1337, p: int = 7777) -> bool:
	if multiplayer.has_multiplayer_peer():
		multiplayer.multiplayer_peer = null
	var peer := ENetMultiplayerPeer.new()
	var err := peer.create_server(p, max_players)
	if err != OK:
		return false
	multiplayer.multiplayer_peer = peer
	is_host = true
	world_seed = seed_value
	WorldManager.seed_world = seed_value
	WorldManager.rebuild_world()
	multiplayer.peer_connected.connect(_on_peer_connected)
	multiplayer.peer_disconnected.connect(_on_peer_disconnected)
	return true


func join_game(address: String, p: int = 7777) -> bool:
	if multiplayer.has_multiplayer_peer():
		multiplayer.multiplayer_peer = null
	var peer := ENetMultiplayerPeer.new()
	var err := peer.create_client(address, p)
	if err != OK:
		return false
	multiplayer.multiplayer_peer = peer
	host_ip = address
	port = p
	multiplayer.connected_to_server.connect(_on_connected_to_server)
	multiplayer.connection_failed.connect(func(): print("NET: connection failed"))
	return true


## ---- Host-side ----

func _on_peer_connected(peer_id: int) -> void:
	print("NET: peer %d connected" % peer_id)
	# Give the client its own local player + seed.
	spawn_local_player.rpc_id(peer_id, world_seed, local_spawn_pos(), peer_id)
	# Notify everyone (including the new peer) to build remote pawns.
	for pid in _active_peer_ids():
		spawn_remote_player.rpc(
			NetworkManager, serialize_peer(pid))


func _on_peer_disconnected(peer_id: int) -> void:
	var pawn: Node = _remote_players.get(peer_id)
	if pawn != null and is_instance_valid(pawn):
		pawn.queue_free()
	_remote_players.erase(peer_id)
	print("NET: peer %d disconnected" % peer_id)


func _active_peer_ids() -> Array:
	var out: Array = [multiplayer.get_unique_id()]
	for id in multiplayer.get_peers():
		out.append(id)
	return out


func serialize_peer(peer_id: int) -> Dictionary:
	var pos := _peer_spawn_pos(peer_id)
	return {"peer": peer_id, "pos": [pos.x, pos.y, pos.z]}


func _peer_spawn_pos(peer_id: int) -> Vector3:
	var base := local_spawn_pos()
	var spread := float(peer_id) * 2.0
	return base + Vector3(spread, 0, spread)


func local_spawn_pos() -> Vector3:
	if WorldManager.spawn_found:
		return WorldManager.spawn_position
	return Vector3(8.5, 62.0, 8.5)


## ---- Client-side ----

func _on_connected_to_server() -> void:
	client_ready.rpc_id(1)


@rpc("any_peer", "reliable", "call_remote")
func client_ready() -> void:
	if not is_host:
		return
	var pid := multiplayer.get_remote_sender_id()
	if not _remote_players.has(pid):
		_remote_players[pid] = _spawn_pawn(pid, _peer_spawn_pos(pid))


## Host -> one client: become a player in the shared world.
@rpc("authority", "reliable", "call_remote")
func spawn_local_player(seed_value: int, spawn_pos: Vector3, own_peer: int) -> void:
	if WorldManager.seed_world != seed_value:
		WorldManager.seed_world = seed_value
		WorldManager.rebuild_world()
	var pawn := _spawn_pawn(own_peer, spawn_pos)
	pawn.is_local = true
	pawn.creative = ProjectSettings.get_setting("application/config/creative_mode", false)
	WorldManager.show_hud()


## Host -> all: add a remote pawn for a peer.
@rpc("any_peer", "reliable", "call_remote")
func spawn_remote_player(sender_node: Object, info: Dictionary) -> void:
	var pid := int(info.peer)
	if is_instance_valid(_remote_players.get(pid)):
		return
	var pos := Vector3(info.pos[0], info.pos[1], info.pos[2])
	var pawn := _spawn_pawn(pid, pos)
	_remote_players[pid] = pawn
	pawn.is_local = false
	pawn.realm = WorldManager.active_realm
	if pid == multiplayer.get_unique_id():
		WorldManager.show_hud()


func _spawn_pawn(pid: int, pos: Vector3) -> Node:
	var pawn: Node = player_scene.instantiate()
	pawn.name = "Player_%d" % pid
	pawn.peer_id = pid
	pawn.global_position = pos
	var players_root: Node = _players_root()
	players_root.add_child(pawn)
	pawn.add_to_group("player")
	seed_player(pawn, pid)
	return pawn


func seed_player(pawn: Node, pid: int) -> void:
	var vitals: Node = pawn.get_node_or_null("VitalStats")
	if vitals != null:
		vitals.setup({
			"max_health": 100.0, "max_hunger": 100.0, "max_thirst": 100.0,
			"health": 100.0, "hunger": 100.0, "thirst": 100.0,
		})
	# Creative kit for dev/testing.
	if ProjectSettings.get_setting("application/config/creative_mode", false):
		for item in ItemIds.CREATIVE_KIT:
			pawn.inventory.add_item(item, 64)


func _players_root() -> Node:
	var scene := get_tree().current_scene
	var root := scene.get_node_or_null("Players")
	if root != null:
		return root
	root = Node3D.new()
	root.name = "Players"
	scene.add_child(root)
	return root


func show_hud_to(pawn: Node) -> void:
	pass


## ---- State sync (20 Hz authoritative + interpolated remotes) ----

func try_send_player_state(player: Node) -> void:
	if not multiplayer.has_multiplayer_peer() or not is_instance_valid(player):
		return
	_state_timer += get_process_delta_time()
	if _state_timer < STATE_INTERVAL:
		return
	_state_timer = 0.0
	if player.is_local:
		sync_player.rpc(self, player.peer_id,
			player.global_position.x, player.global_position.y, player.global_position.z,
			player.realm, player.flying)


@rpc("any_peer", "unreliable_ordered", "call_remote")
func sync_player(sender: Object, pid: int, px: float, py: float, pz: float, realm: int, flying: bool) -> void:
	if pid == multiplayer.get_unique_id():
		return
	var pawn := _remote_players.get(pid)
	if pawn == null or not is_instance_valid(pawn):
		return
	pawn.remote_target = Vector3(px, py, pz)
	if pawn.realm != realm:
		pawn.realm = realm
	pawn.flying = flying


## ---- Block edits ----

## Local authoritative call: host applies + relays, clients forward to host.
func submit_block_edit(player: Node, pos: Vector3i, id: int, meta: int, realm: int) -> void:
	if not is_online():
		return
	if is_host:
		_apply_edit_sim(pos, id, meta, realm)
	else:
		host_block_edit.rpc_id(1, pos, id, meta, realm)


@rpc("any_peer", "reliable", "call_remote")
func host_block_edit(pos: Vector3i, id: int, meta: int, realm: int) -> void:
	if not is_host:
		return
	_apply_edit_sim(pos, id, meta, realm)


@rpc("authority", "reliable", "call_remote")
func apply_edit_sync(pos: Vector3i, id: int, meta: int, realm: int) -> void:
	if not is_host:
		_apply_edit_sim(pos, id, meta, realm)


func _apply_edit_sim(pos: Vector3i, id: int, meta: int, realm: int) -> void:
	_applying_remote = true
	WorldManager._set_block_inst(realm, pos, id, meta)
	_applying_remote = false


func rpc_block_edit(pos: Vector3i, id: int, meta: int, realm: int) -> void:
	submit_block_edit(null, pos, id, meta, realm)


## Keep by-name reference for WorldManager calls.
func on_edit(_player: Node, pos: Vector3i, id: int, meta: int) -> void:
	rpc_block_edit(pos, id, meta, WorldManager.active_realm)


## ---- Realm spawns ----

func realm_spawn_point(realm: int) -> Vector3:
	var gen: WorldGenerator = WorldManager.generator_for(realm)
	match realm:
		WorldGenerator.Realm.NETHER:
			var n := gen.nether_noise_sample(Vector2(0, 0))
			return Vector3(0.5, 44.0 + n * 8.0 + 1.0, 0.5)
		WorldGenerator.Realm.HEAVEN:
			return gen.heaven_island_spot()
	return local_spawn_pos()


## Host may also need to keep local player on realm switches.
func teleport_local(realm: int, pos: Vector3) -> void:
	var pawn: Node = _players_root().get_node_or_null("Player_%d" % multiplayer.get_unique_id())
	if pawn != null and is_instance_valid(pawn):
		WorldManager.switch_player_realm(pawn, realm, pos)","filePath":"/home/work/voxel_survival/scripts/networking/network_manager.gd"}

