add='''## Reset every realm for a new seed (host side) / seed confirmation (client).
func rebuild_world() -> void:
	generators.clear()
	chunk_data.clear()
	chunk_queued.clear()
	for realm_id in REALMS:
		var gen := WorldGenerator.new(realm_id, seed_world + REALMS[realm_id].seed_shift)
		generators[realm_id] = gen
		chunk_data[realm_id] = {}
		chunk_queued[realm_id] = {}
	for root in realm_roots.values():
		if is_instance_valid(root):
			root.queue_free()
	realm_roots.clear()
	for realm_id in REALMS:
		var root := Node3D.new()
		root.name = "Realm_%d" % realm_id
		add_child(root)
		realm_roots[realm_id] = root
	chunk_nodes.clear()
	spawn_found = false
	_find_spawn_later()


## Ensure the HUD exists (single-player boot + multiplayer join).
