## Simple realm environment driver: adjusts WorldEnvironment sky/fog when the
## active realm changes. Declaration-only for now - the Environment resource can
## be swapped here without any Editor interaction.
##
## Hooked into WorldManager.set_active_realm() via the "world_env" group.

@onready var env: WorldEnvironment = get_node_or_null("Env")


func apply_realm(realm: int) -> void:
	if env == null:
		return
	var e: Environment = env.environment
	if e == null:
		return
	var meta := WorldManager.REALMS.get(realm, WorldManager.REALMS[WorldGenerator.Realm.OVERWORLD])
	e.clear_color = meta.sky
	e.fog_enabled = true
	e.fog_density = 1.0 / maxf(meta.fog_dist, 1.0)
	e.fog_light_color = meta.sky
	e.ambient_light_source = Environment.AMBIENT_SOURCE_COLOR
	e.ambient_light_color = meta.sky * 0.6
	e.ambient_light_energy = 1.0
	if realm == WorldGenerator.Realm.NETHER:
		e.ambient_light_energy = 0.45","filePath":"/home/work/voxel_survival/scripts/main/world_env.gd"}

