## Headless test runner. Usage:
##   godot4 --headless --path . res://tests/test_runner.tscn
## Quits with exit code = number of failing suites (0 = all green).

const SUITES := [
	"res://tests/test_inventory.gd",
	"res://tests/test_survival.gd",
	"res://tests/test_crafting.gd",
	"res://tests/test_energy.gd",
	"res://tests/test_worldgen.gd",
]

func _ready() -> void:
	# Give autoloads (WorldManager.spawn search, etc.) a moment to breathe.
	get_tree().create_timer(0.2).timeout \
		.connect(func():
			var failed := 0
			for path in SUITES:
				var script: GDScript = load(path)
				var test := script.new()
				var fails: int = test.run()
				failed += fails
			if failed == 0:
				print("=== ALL SUITES PASSED ===")
			else:
				print("=== %d EXPECTATION(S) FAILED ===" % failed)
			get_tree().quit(failed))

func _notification(what: int) -> void:
	if what == NOTIFICATION_WM_CLOSE_REQUEST:
		get_tree().quit(0)","filePath":"/home/work/voxel_survival/tests/run_tests.gd"}

